#!/usr/bin/env bash\nset -e\n\n# Ensure we are in the module directory\ncd "$(dirname \"$0\")/.."\n\n# Initialize Terraform (no remote backend)\nterraform init -backend=false > /dev/null\n\n# Validate configuration\nterraform validate\n\n# Apply the module (auto‑approve, no interactive input)\nterraform apply -auto-approve -input=false > /dev/null\n\n# Verify that the supply list file was created and contains expected content\nif [[ -f supply_list.txt ]]; then\n  grep -q \"canned beans\" supply_list.txt\n  echo "✅ supply_list.txt created and contains expected items"\nelse\n  echo "❌ supply_list.txt was not created"\n  exit 1\nfi\n
